__NUXT_JSONP__("/price", (function(a,b,c,d,e,f,g,h,i,j,k,l){return {data:[{details:{slug:"en",pageTitle:"Prices | Mentor Language Institute",pageDescription:"If you provide your own accommodation, you do not need to pay the ②Accommodation fee. *Please use the price calculator to get a quote.",title:"Prices",image:"\u002Fimages\u002Fprices\u002Fprice\u002Fget-a-quote.jpg",button:{lists:[{link:["\u003Ca class=\"btn btn-primary\" href=\"\u002Fprice-auto\"\u003EPrice Calculator\u003C\u002Fa\u003E"]}]},steps:{title:"①Tuition ＋ ②Accommodation Fee ＋ ③Other fees",subtitle:["If you provide your own accommodation, you do not need to pay the ②Accommodation fee.\u003Cbr\u003E*Please use \u003Ca href=\"\u002Fprice-auto\u002F\"\u003Ethe price calculator\u003C\u002Fa\u003E to get a quote."],lists:[{title:"①Tuition",subtitle:["The price will change depending on your course and the duration of your stay.\u003Cbr \u002F\u003EThe longer you study at MLI, the bigger the discount."],image:"\u002Fimages\u002Fprices\u002Fprice\u002FPRICE_CHART_WEB_JAN06.jpg",link:["\u003Cb\u003EQ&A\u003C\u002Fb\u003E","\u003Cb\u003EQ1: Can I pay the fees by credit card? \u003C\u002Fb\u003E \u003Cbr \u002F\u003E\u003Cb\u003EA1:\u003C\u002Fb\u003E Yes, you may pay your fees by credit card. However, a 4% service charge will be added.","\u003Cb\u003EQ2: What methods of payment can I use to pay MLI? \u003C\u002Fb\u003E \u003Cbr \u002F\u003E\u003Cb\u003EA2:\u003C\u002Fb\u003E We accept the following payment methods: \u003Cbr\u003E • Bank Transfer \u003Cbr\u003E • International Money Wire \u003Cbr\u003E • Cash \u003Cbr\u003E • Personal Check \u003Cbr\u003E • Credit Card \u003Cbr\u003E • Debit Card \u003Cbr\u003E • Zelle","If you would like to avoid the 4% service charge for credit\u002Fdebit card payments, you may choose one of these alternatives: \u003Cbr\u003E\u003Cb\u003EBank Transfer, International Money Wire (a $35 bank fee applies), Cash, Personal Check, or Zelle. \u003C\u002Fb\u003E","\u003Cb\u003EQ3: Can I pay my tuition after I start my program? \u003C\u002Fb\u003E \u003Cbr \u002F\u003E\u003Cb\u003EA3:\u003C\u002Fb\u003E No. Full payment must be made \u003Cb\u003Ebefore\u003C\u002Fb\u003E  or \u003Cb\u003Eon the first day\u003C\u002Fb\u003E  of your program."],category:[{title:"Optional Service",table:{tableMaxCol:c,title_optional:"Change of Status(If you have B1\u002FB2 or J1 visa and are currently in the U.S.) or Reinstatement",tbody:[["\u003Cb\u003EFee descriptions\u003C\u002Fb\u003E","\u003Cb\u003EType of Applicants\u003C\u002Fb\u003E","\u003Cb\u003EFees\u003C\u002Fb\u003E","\u003Cb\u003ENumber of Applicants\u003C\u002Fb\u003E"],["$1,885 Service Fee including Filling Fee ($370) and Mailing Fee \u003Cbr\u003E *Upon approval, $600 will be applied as a tuition credit for the student (non-cash value).","F1 student visa","$1,885","1"],["$365 Service Fee for each dependent","F2 dependant visa","$365",b]]}}]},{title:"②Accommodation Fee",subtitle:["We provide homestay and domitory options for students. Homestay is recommended for people who would like to experience American culture. Dormitories are recommended for people who would like to make a lot of friends."],category:[{title:"Homestay Prices",table:{tableMaxCol:3,title:"Placement Fee* : $300\u003Cbr \u002F\u003E If younger than 18 years old, the rent will be approximately 10% higher than the price for a person older than 18 years old.",thead:[b,d,"Shared***"],tbody:[[e,a,a],[f,"$436","$384"],[g,"$872","$768"],[h,"$1,308","$1,152"],[i,"$1,744","$1,536"],[j,"$3,160","$2,904"],[k,"$4,740","$4,356"]]}},{title:"Dormitory Prices",table:{tableMaxCol:c,title:"Placement Fee* : $200\u003Cbr \u002F\u003E If younger than 18 years old, the rent will be approximately 10% higher than the price for a person older than 18 years old.",thead:[b,d,"Shared","Quad"],tbody:[[e,a,a,a],[f,"$570","$430","$315"],[g,"$1,140","$860","$630"],[h,"$1,710","$1,290","$945"],[i,"$2,280","$1,720","$1,260"],[j,"$4,320","$3,080","$2,320"],[k,"$6,480","$4,620","$3,480"]]},description:["*Placement fee is a one time payment. It's not refundable.\u003Cbr \u002F\u003E**Security deposit will be refunded after students have moved out.\u003Cbr \u002F\u003E***If you request a homestay shared room, \u003Cspan class=\"rmarker\"\u003Eyou must apply with another person.\u003C\u002Fspan\u003E","※Your accommodation will be provided by U.S. Support Service Inc. or other agents.","\u003Ca href=\"\u002Fstay\u002F\"\u003E\u003Ci class='bi bi-arrow-right'\u003E\u003C\u002Fi\u003E  More information about Accommodations\u003C\u002Fa\u003E"]}]},{title:"③Initial Fees",subtitle:["In addition to the fees above, there are other initial fees."],lists:["Initial Processing Fee* ： $150","I-20 Mailing Fee** : $120","SEVIS fee** ： $350 (Paid directly to SEVP)","Textbook ： $150-240"],description:["*Non-refundable\u003Cbr \u002F\u003E**If Student Visa applied"]}]},examples:{title:"Examples",subtitle:["Examples of payments : 1 month (4 weeks) and 1 year (48 weeks)"],lists:[{title:"1 month (4 weeks)",items:["Initial(Processing) Fee : $150","Tuition : $1,220","Housing (Dormitory : Quad Rent + Placement Fee + Airport Pickup - one way):  $1,630","\u003Cspan class='total'\u003ETotal : $3,000\u003C\u002Fspan\u003E"]},{title:"1 year (48 weeks)",items:["Initial(Processing) fee : $150","Tuition : $10,032","Housing (Dormitory : Quad Rent + Placement Fee + Airport Pickup - one way):  $13,810","\u003Cspan class='total'\u003ETotal : $23,992\u003C\u002Fspan\u003E"]}]},other_info:["If you have any questions about fees, please feel free to contact us."],dir:"\u002Fprice",path:"\u002Fprice\u002Fen",extension:".json",createdAt:"2026-10-22T16:31:30.166Z",updatedAt:"2026-03-24T13:34:16.710Z"},lang:l}],fetch:{},mutations:l}}("$300","",4,"Private","\u003Cb\u003EDeposit\u003C\u002Fb\u003E","1 week","2 weeks","3 weeks","4 weeks","8 weeks","12 weeks",void 0)));